<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/paid-block-custom-title-10 {"mainTitle":"徒歩◯分の数え方","subTitle":"ACCESS","headingLevel":2,"sizeClass":"size_l","positionClass":"position_center","mainTitleColor":"var(--color-main)","leftImage":"","rightImage":"","bdDisplay":"on","bdThickness":2} -->
<div class="wp-block-wdl-paid-block-custom-title-10 paid-block-custom-title-10 position_center size_l"><h2 class="ttl"><span class="text_wrap"><span class="sub" style="color:var(--color-main)">ACCESS</span><span class="main">徒歩◯分の数え方</span></span><span class="bd" style="background-color:var(--color-main);height:2px;margin-top:0.1em"></span></h2></div>
<!-- /wp:wdl/paid-block-custom-title-10 -->
<!-- wp:paragraph {"align":"center"} -->
<p class="has-text-align-center">広告の「徒歩◯分」には決まりがあります。<span class="lw-br on_500px"></span>知っておくと、内見のときに見るところが変わります。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-waku-1 {"waku1MaxWidthPc":900,"waku1PaddingTopPc":28,"waku1PaddingBottomPc":28,"waku1PaddingLeftPc":32,"waku1PaddingRightPc":32,"waku1PaddingTopSp":20,"waku1PaddingBottomSp":20,"waku1PaddingLeftSp":16,"waku1PaddingRightSp":16,"waku1BorderWidthPc":1,"waku1BorderWidthSp":1,"waku1BorderColorPc":"#e5e9ee","waku1BorderColorSp":"#e5e9ee","waku1BorderRadiusPc":[8,8,8,8],"waku1BgColorPc":"#f7f7f5"} -->
<div class="wp-block-wdl-lw-pr-waku-1 lw-pr-waku-1" style="--waku-1-justify-content-pc:center;--waku-1-justify-content-sp:center"><div class="lw-pr-waku-1__custom_wrap" style="--waku-1-max-width-pc:900px;--waku-1-max-width-sp:900px;--waku-1-padding-pc:28px 32px 28px 32px;--waku-1-padding-sp:20px 16px 20px 16px;--waku-1-bd-width-pc:1px;--waku-1-bd-width-sp:1px;--waku-1-bd-style-pc:solid;--waku-1-bd-style-sp:solid;--waku-1-bd-color-pc:#e5e9ee;--waku-1-bd-color-sp:#e5e9ee;--waku-1-bdr-pc:8px 8px 8px 8px;--waku-1-bdr-sp:8px 8px 8px 8px;--waku-1-bg-pc:#f7f7f5;--waku-1-bg-sp:#f7f7f5;--waku-1-bg-opacity-pc:1;--waku-1-bg-opacity-sp:1;--waku-1-blend-mode-pc:normal;--waku-1-blend-mode-sp:normal;--waku-1-bg-img-pc:none;--waku-1-bg-img-sp:none;--waku-1-img-filter-pc:none;--waku-1-img-filter-sp:none;--waku-1-min-height-pc:auto;--waku-1-min-height-sp:auto;--waku-1-aspect-ratio-pc:auto;--waku-1-aspect-ratio-sp:auto"><!-- wp:heading {"level":3,"textAlign":"center","style":{"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"14px"}}}} -->
<h3 class="has-text-align-center" style="font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:14px">徒歩の表示について</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:0px;margin-bottom:0px"><strong>計算のしかた</strong>　道のり80mを1分として計算します（不動産の表示に関する公正競争規約）。端数は切り上げなので、81mでも2分と書かれます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"10px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:10px;margin-bottom:0px"><strong>入っていないもの</strong>　信号待ち・踏切・坂道・階段の時間は入っていません。このあたりは踏切が多いので、朝は表示より5分ほど多くみてください。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"10px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:10px;margin-bottom:0px"><strong>どこからどこまで</strong>　物件の敷地の入口から、駅の一番近い出入口までです。ホームまでの時間は入りません。地下駅では3〜5分の差が出ます。</p>
<!-- /wp:paragraph -->
<!-- wp:paragraph {"style":{"typography":{"fontSize":"15px"},"spacing":{"margin":{"top":"10px","bottom":"0px"}}}} -->
<p style="font-size:15px;margin-top:10px;margin-bottom:0px"><strong>確かめ方</strong>　気になる物件は、**平日の朝の同じ時間に一度歩いてみる**ことをお勧めしています。ご希望があれば、その時間に合わせてご案内します。</p>
<!-- /wp:paragraph --></div></div>
<!-- /wp:wdl/lw-pr-waku-1 -->
<!-- wp:wdl/lw-space-1 {"pcHeight":80,"tbHeight":64,"spHeight":40} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:80px"></div><div class="tb" style="height:64px"></div><div class="sp" style="height:40px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/paid-block-custom-title-10 {"mainTitle":"内見の流れ","subTitle":"VIEWING","headingLevel":2,"sizeClass":"size_l","positionClass":"position_center","mainTitleColor":"var(--color-main)","leftImage":"","rightImage":"","bdDisplay":"on","bdThickness":2} -->
<div class="wp-block-wdl-paid-block-custom-title-10 paid-block-custom-title-10 position_center size_l" id="flow"><h2 class="ttl"><span class="text_wrap"><span class="sub" style="color:var(--color-main)">VIEWING</span><span class="main">内見の流れ</span></span><span class="bd" style="background-color:var(--color-main);height:2px;margin-top:0.1em"></span></h2></div>
<!-- /wp:wdl/paid-block-custom-title-10 -->
<!-- wp:paragraph {"align":"center"} -->
<p class="has-text-align-center">1日に3〜4件がめやすです。半日みていただければ、だいたい決まります。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/paid-block-lw-step-4 {"ulMaxWidth":900,"fontSizeClass":"font_size_m","bgGradient":"color-mix(in srgb, var(--color-main) 50%, #000)","colorNo":"color-mix(in srgb, var(--color-main) 50%, #000)","titleTag":"h3"} -->
<div class="wp-block-wdl-paid-block-lw-step-4 paid-block-lw-step-4 font_size_m"><ul class="lw-step__inner" style="max-width:900px"><li class="lw-step__li" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:color-mix(in srgb, var(--color-main) 50%, #000)">01</div><div class="lw-step__li_in"><h3 class="lw-step__li_title ttl" data-lw_font_set="">希望の日を教えてください</h3><p class="lw-step__li_text" data-lw_font_set="">前日までにご連絡いただければ、その日のうちに回れるよう順番を組みます。
当社で鍵をお預かりしている物件は、当日のお申し出でもご案内できます。</p></div></li><li class="lw-step__li" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:color-mix(in srgb, var(--color-main) 50%, #000)">02</div><div class="lw-step__li_in"><h3 class="lw-step__li_title ttl" data-lw_font_set="">店舗に集合、車で回ります</h3><p class="lw-step__li_text" data-lw_font_set="">当社の車でお送りします。現地集合をご希望の方はその旨をお伝えください。
お子さん連れの方はチャイルドシートをご用意しますので、年齢だけ先に教えてください。</p></div></li><li class="lw-step__li" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:color-mix(in srgb, var(--color-main) 50%, #000)">03</div><div class="lw-step__li_in"><h3 class="lw-step__li_title ttl" data-lw_font_set="">部屋を見ます</h3><p class="lw-step__li_text" data-lw_font_set="">1件あたり15〜20分です。メジャーと間取り図をお渡しするので、洗濯機置き場と冷蔵庫の幅は必ず測ってください。
写真を撮っていただいて構いません（あとで見返すと必ず記憶が混ざります）。</p></div></li><li class="lw-step__li" style="border-color:color-mix(in srgb, var(--color-main) 50%, #000)"><div class="lw-step__li_no" data-lw_font_set="Murecho" style="font-weight:600;color:color-mix(in srgb, var(--color-main) 50%, #000)">04</div><div class="lw-step__li_in"><h3 class="lw-step__li_title ttl" data-lw_font_set="">店舗で費用を出します</h3><p class="lw-step__li_text" data-lw_font_set="">気になった物件について、初期費用と毎月の支払いを紙に書き出します。
その場でお決めいただく必要はありません。持ち帰ってご家族と相談される方がほとんどです。</p></div></li></ul></div>
<!-- /wp:wdl/paid-block-lw-step-4 -->
